  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C63"],
      "claim": "Disopyramide, which shares the central phenyl/pyridin-2-yl carbon and basic amine side chain with the query, has an absolute oral bioavailability of 78.23 ± 16.18% in normal volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Vismodegib, which contains a pyridin-2-yl group, has an absolute oral bioavailability of 31.8% after a 150 mg oral dose, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Methadone, a lipophilic basic drug with a similar tertiary carbon center, has an absolute oral bioavailability of 0.85 (95% CI 0.79-0.92) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is structurally analogous to disopyramide (absolute F ~78%) and contains a pyridin-2-yl group seen in other high-bioavailability drugs (vismodegib 31.8%, atazanavir 60-68%, pritelivir 75%). No affirmative evidence supports F below 20%; therefore, predict high.",
  "evidence_gaps": [
    "No direct experimental data for the query molecule itself.",
    "Closest analogue disopyramide differs by a carboxamide vs hydroxyl and a different amine side chain; the effect of the 2,6-dimethylpiperidine moiety on absorption is not directly tested."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

